#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        // 49 → 50: system.codebase.atlas.register added (the staged rebuild's promotion step).
        assert_eq!(a.len(), 50, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
